using System;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;
partial class TerminalWindow {
 string codexTab="额度与提醒";ComboBox quotaQueryMode;
 void BuildCodexReminders(Panel body,MonitorConfig cfg){var q=cfg.Quota;SettingsLabel(body,"额度查询与周期状态");quotaQueryMode=TaskbarChoice(body,"额度查询模式",new[]{"关闭额度查询","仅手动查询","自动查询 · 每60秒","每天固定时间查询"},!q.Enabled?0:q.BackgroundRefresh?(q.ScheduledRefresh?3:2):1);quotaQueryMode.Width=230;quotaQueryMode.SelectionChanged+=(s,e)=>{int mode=quotaQueryMode.SelectedIndex;if(mode<0)return;bool enabled=mode!=0,background=mode>=2,scheduled=mode==3;if(q.Enabled==enabled&&q.BackgroundRefresh==background&&q.ScheduledRefresh==scheduled)return;SaveMonitor(()=>{q.Enabled=enabled;q.BackgroundRefresh=background;q.ScheduledRefresh=scheduled;});};var queryTimes=TaskbarInput(body,"固定查询时间（本地时间，逗号分隔）",q.QueryTimes,260);Button(body,"保存查询时间",()=>{var times=CodexQuotaReader.ParseQueryTimes(queryTimes.Text);SaveMonitor(()=>q.QueryTimes=String.Join(", ",times));});SettingDescription(body,"固定时间仅在桌宠运行时查询；错过时刻不补查。为确认待启动周期，可能在一分钟后追加一次核验；手动刷新始终可用。");MonitorToggle(body,"检测到新周期或额度回升时提醒",()=>q.ResetDetectedAlerts,v=>q.ResetDetectedAlerts=v);SettingDescription(body,"桌宠运行且已授权时，按所选模式读取官方额度，不发送模型请求；休眠或关机期间无法查询，恢复后核验。查询不会启动官方尚未开始的周期，也不会消耗或兑换重置券。仅按官方返回时间更新倒计时，不用本机首次发现时间推算。手动查询模式下仍可在连接页面测试或刷新。");SettingsLabel(body,"剩余额度与重置前提醒");MonitorToggle(body,"剩余额度不足时提醒",()=>q.Alerts,v=>q.Alerts=v);MonitorToggle(body,"额度即将重置时提醒",()=>q.ResetReminder,v=>q.ResetReminder=v);var five=MemoPoints(body,"五小时剩余额度（%）",ThresholdPoints.Effective(q.FiveHourThresholds,q.FiveHourThreshold,0,100),0,100,"5, 10, 20");var week=MemoPoints(body,"周剩余额度（%）",ThresholdPoints.Effective(q.WeeklyThresholds,q.WeeklyThreshold,0,100),0,100,"5, 10, 20");var reset=MemoPoints(body,"重置前提醒（分钟）",(q.ResetReminderPoints??new List<int>{q.ResetReminderMinutes}).Select(x=>(double)x),1,1440,"1, 5, 15, 30");SettingDescription(body,"剩余额度下降到各点分别提醒；同周期去重。重置前多个时间点分别提醒，休眠或首次打开错过多个点时只发最近的一次。原声提示不重复朗读每秒倒计时。");Button(body,"保存额度与重置提醒",()=>{var f=ThresholdPoints.Parse(five.Text,0,100);var w=ThresholdPoints.Parse(week.Text,0,100);var points=ThresholdPoints.Parse(reset.Text,1,1440);if(points.Any(x=>x!=Math.Floor(x)))throw new ArgumentException("提前分钟请输入整数。");SaveMonitor(()=>{q.FiveHourThresholds=f.ToList();q.WeeklyThresholds=w.ToList();q.FiveHourThreshold=f[0];q.WeeklyThreshold=w[0];q.ResetReminderPoints=points.Select(x=>(int)x).ToList();q.ResetReminderMinutes=q.ResetReminderPoints[0];});});BuildWakeSettings(body,q);}
 void BuildCodexHub(){var navigation=new WrapPanel{Margin=new Thickness(0,0,0,12)};var host=new ContentControl{HorizontalContentAlignment=HorizontalAlignment.Stretch};content.Children.Add(navigation);content.Children.Add(host);var names=new[]{"会话动态","额度与提醒","重置记录","连接与微信","订阅"};var buttons=new Dictionary<string,Button>();Action<string> select=tab=>{codexTab=tab;quotaQueryMode=null;monitorChecks.Clear();if(tab=="会话动态")host.Content=MemoSection("Codex状态");else{StackPanel body;var panel=Panel("Codex · "+tab,"tasks",out body);var cfg=assistant.Config.Monitor;if(tab=="额度与提醒")BuildCodexReminders(body,cfg);else if(tab=="重置记录"){BuildQuotaTimeline(body,cfg.Quota);BuildQuotaAudit(body);Button(body,"查看额度历史曲线",()=>{archiveTab="额度轨迹";ShowPage("线索档案馆");});}else if(tab=="连接与微信"){BuildQuotaSettings(body,cfg);BuildQuotaPhone(body,cfg.Quota);}else BuildSubscriptionSettings(body,cfg.Quota);host.Content=panel;}foreach(var b in buttons)b.Value.Tag=b.Key==tab?"selected":null;TerminalAppearance.BindTree(host);VisualEffects.Apply(host);RefreshMonitor();};foreach(string title in names){string tab=title;buttons[tab]=Button(navigation,tab,()=>select(tab));}select(names.Contains(codexTab)?codexTab:"额度与提醒");}
}
